import 'dart:convert';import 'package:flutter/material.dart';import 'chat_doctor.dart';import 'chat_page.dart'; // ✅ Ensure this import is presentimport 'mongo_service.dart';import 'status.dart';class ChatSelectionPage extends StatefulWidget {  const ChatSelectionPage({super.key});  @override  State<ChatSelectionPage> createState() => _ChatSelectionPageState();}class _ChatSelectionPageState extends State<ChatSelectionPage> {  List<dynamic> _pets = [];  String? _selectedPetId;  String? _selectedPetName;  String? _selectedAvatar;  @override  void initState() {    super.initState();    _loadPets();  }  Future<void> _loadPets() async {    final pets = await MongoDatabase.getUserPets(userId);    String? matchedId;    String? matchedAvatar;    for (var p in pets) {      if (p['name'] == pet) {        matchedId = p['pet_id'];        matchedAvatar = p['avatar'];        break;      }    }    setState(() {      _pets = pets;      _selectedPetId = matchedId;      _selectedPetName = pet;      _selectedAvatar = matchedAvatar;    });  }  bool _isValidBase64(String? str) {    if (str == null || str.isEmpty || str.length % 4 != 0) return false;    try {      base64Decode(str);      return true;    } catch (_) {      return false;    }  }  ImageProvider _getAvatarImage(String? base64Str) {    if (_isValidBase64(base64Str)) {      try {        return MemoryImage(base64Decode(base64Str!));      } catch (_) {        return const AssetImage('assets/default_pet.png');      }    } else {      return const AssetImage('assets/default_pet.png');    }  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text("Chat Options"),        actions: [          if (_pets.isNotEmpty)            Padding(              padding: const EdgeInsets.only(right: 12.0),              child: DropdownButtonHideUnderline(                child: DropdownButton<String>(                  value: _selectedPetId,                  dropdownColor: Colors.white,                  items: _pets.map((petObj) {                    return DropdownMenuItem<String>(                      value: petObj['pet_id'],                      child: Row(                        children: [                          CircleAvatar(                            radius: 12,                            backgroundImage: _getAvatarImage(petObj['avatar']),                          ),                          const SizedBox(width: 8),                          Text(petObj['name'],                              style: const TextStyle(fontSize: 14)),                        ],                      ),                    );                  }).toList(),                  onChanged: (val) {                    final selected =                        _pets.firstWhere((e) => e['pet_id'] == val);                    setState(() {                      _selectedPetId = val;                      _selectedPetName = selected['name'];                      _selectedAvatar = selected['avatar'];                      pet = selected['name'];                    });                  },                ),              ),            ),        ],      ),      body: Padding(        padding: const EdgeInsets.all(20.0),        child: Column(          mainAxisAlignment:              MainAxisAlignment.center, // Center content vertically          crossAxisAlignment:              CrossAxisAlignment.center, // Center content horizontally          children: [            // **🔹 Chat Selection Text**            const Text(              "Please select your preferred chat option:",              style: TextStyle(                fontSize: 18,                fontWeight: FontWeight.bold,              ),              textAlign: TextAlign.center,            ),            const SizedBox(height: 20),            const Text(              "• Looking for instant responses and initial advice? Try our AI Assistant.\n"              "• Need professional medical consultation? Choose to chat with a real doctor.",              style: TextStyle(fontSize: 16),              textAlign: TextAlign.center,            ),            const SizedBox(height: 40),            // **🔹 Chat Options**            _buildChatOptionButton(              label: "Chat with AI",              icon: Icons.smart_toy,              onTap: () {                Navigator.push(                  context,                  MaterialPageRoute(                      builder: (context) =>                          const ChatPage()), // ✅ Now correctly recognized                );              },            ),            const SizedBox(height: 20),            _buildChatOptionButton(              label: "Chat with a Doctor",              icon: Icons.local_hospital,              onTap: () {                Navigator.push(                  context,                  MaterialPageRoute(                      builder: (context) =>                          const ChatDoctorPage()), // ✅ Now correctly recognized                );              },            ),          ],        ),      ),    );  }  /// **🔹 Helper Method to Create Chat Option Buttons**  Widget _buildChatOptionButton(      {required String label,      required IconData icon,      required VoidCallback onTap}) {    return SizedBox(      width: 280, // Ensure button width      child: ElevatedButton.icon(        onPressed: onTap,        icon: Icon(icon, color: Colors.white),        label: Text(label),        style: ElevatedButton.styleFrom(          backgroundColor: Colors.blueAccent,          foregroundColor: Colors.white,          padding: const EdgeInsets.symmetric(vertical: 12),          textStyle: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold),          shape: RoundedRectangleBorder(            borderRadius: BorderRadius.circular(8),          ),        ),      ),    );  }}